Order.onAddObject:
add_object('lmdbB', 'Audit',
    {op: 'add', orderId: current::objectId, item: current::object.item},
    current::objectId + '-add');
return current::useDefaultProcessing;

auditCount.onGetProperty:
const rows: array = retrieve_objects('lmdbB', 'Audit',
    {filter: {op: 'eq', property: 'orderId', value: current::mappedObjectId}});
return length(rows);

OrderThrow.onAddObject:
add_object('lmdbB', 'Audit', {op: 'add', orderId: current::object.item},
    current::object.item + '-add');
add_object(current::mappedAdapterId, 'OrderRow', current::object,
    current::object.item);
throw 'OrderThrow: abort after writing lmdbA and lmdbB';

OrderFillSmall.onAddObject:
const s = repeat<string>('xxxx', 1000);
for (let i = 0; i < 2000; i = i + 1) {
    try {
        add_object('lmdbSmall', 'Fill', {s: s});
    }
    catch (e) {
        break;
    }
}
return current::useDefaultProcessing;

OrderSelfNote.onAddObject:
add_object(current::mappedAdapterId, 'OrderNote',
    {orderId: current::objectId, item: current::object.item},
    current::objectId + '-note');
return current::useDefaultProcessing;
